            padding: 1.75rem 1.25rem;
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
            scroll-behavior: smooth;
        }

        @keyframes message-pop-in {
            from {
                opacity: 0;
                transform: translateY(8px) scale(0.98);
            }
            to {
                opacity: 1;
                transform: translateY(0) scale(1.0);
            }
        }

        .message {
            max-width: 85%;
            padding: 14px 20px;
            border-radius: 22px;
            line-height: 1.55;
            font-size: 0.98rem;
            word-wrap: break-word;
            word-break: break-word;
            font-weight: 400;
            white-space: pre-wrap;
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            border: 1px solid rgba(255, 255, 255, 0.08);
        }

        .message:not(.widget) {
            animation: message-pop-in 0.35s cubic-bezier(0.25, 1, 0.5, 1);
        }

        .message.user {
            background: var(--user-bubble-bg);
            color: #fff;
            align-self: flex-end;
            border-bottom-right-radius: 6px;
        }

        .message.ai {
            background: var(--ai-bubble-bg);
            color: var(--text-primary);
            align-self: flex-start;
            border-bottom-left-radius: 6px;
            border: 1px solid rgba(255, 255, 255, 0.06);
        }

        .message.ai.error {
            background: rgba(58, 21, 21, 0.6);
            border: 1px solid rgba(85, 34, 34, 0.5);
            color: #FFB3B3;
        }

        .message.ai.typing-indicator {
            background: var(--ai-bubble-bg);
            padding: 14px 20px;
            align-self: flex-start;
            border: 1px solid rgba(255, 255, 255, 0.06);
        }

        .message-wrapper {
            display: flex;
            flex-direction: column;
            gap: 8px;
            max-width: 85%;
            width: auto;
        }

        .message-wrapper.user {
            align-self: flex-end;
            align-items: flex-end;
        }

        .message-wrapper.ai {
            align-self: flex-start;
            align-items: flex-start;
        }

        .copy-button {
            background: rgba(255, 255, 255, 0.02);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 8px;
            padding: 6px 12px;
            color: var(--text-secondary);
            font-size: 0.75rem;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 6px;
            transition: all 0.2s ease;
            width: fit-content;
        }

        .copy-button:hover {
            background: rgba(255, 255, 255, 0.06);
            border-color: rgba(255, 255, 255, 0.12);
            color: var(--text-primary);
        }

        .copy-button svg {
            width: 12px;
            height: 12px;
        }

        .typing-dot {
            display: inline-block;
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--text-secondary);
            animation: typing-ios 1.4s infinite;
        }

        .typing-dot:nth-child(2) {
            animation-delay: 0.2s;
        }

        .typing-dot:nth-child(3) {
            animation-delay: 0.4s;
        }

        @keyframes typing-ios {
            0%, 60%, 100% {
                transform: scale(0.5);
                opacity: 0.4;
            }
            30% {
                transform: scale(1.0);
                opacity: 1;
            }
        }

        .message.widget {
            max-width: 95%;
            align-self: center;
            width: 100%;
            background: var(--widget-bg);
            backdrop-filter: blur(25px) saturate(200%);
            -webkit-backdrop-filter: blur(25px) saturate(200%);
            border: 1px solid var(--widget-border);
            border-radius: 16px;
            padding: 20px;
            cursor: pointer;
            transition: transform 0.2s ease;
        }

        .message.widget:hover {
            transform: translateY(-2px);
        }

        .widget-header {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-bottom: 16px;
        }

        .widget-header svg {
            width: 24px;
            height: 24px;
            color: var(--accent-blue);
            flex-shrink: 0;
        }

        .widget-header h3 {
            font-size: 1.05rem;
            font-weight: 500;
        }

        .widget-body .task-goal {
            font-size: 0.9rem;
            color: var(--text-secondary);
            margin-bottom: 16px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .widget-body .task-params-summary {
            font-size: 0.8rem;
            color: var(--accent-blue);
            margin-bottom: 16px;
            font-style: italic;
        }

        .widget-status {
            font-size: 0.85rem;
            color: var(--text-primary);
            margin-bottom: 8px;
        }

        .widget-progress-bar {
            width: 100%;
            height: 4px;
            background: rgba(255, 255, 255, 0.08);
            border-radius: 2px;
            overflow: hidden;
        }

        .widget-progress-inner {
            width: 0%;
            height: 100%;
            background: var(--accent-research-gradient);
            transition: width 0.6s ease-out;
        }

        footer {
            position: sticky;
            bottom: 0;
            width: 100%;
            background: var(--header-footer-bg);
            backdrop-filter: blur(30px) saturate(200%);
            -webkit-backdrop-filter: blur(30px) saturate(200%);
            border-top: 1px solid var(--widget-border);
            z-index: 10;
            padding: 12px 16px;
            padding-bottom: calc(12px + var(--safe-bottom));
        }

        #message-form {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        #add-button {
            background: rgba(28, 28, 30, 0.4);
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 50%;
            width: 36px;
            height: 36px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
            cursor: pointer;
            transition: all 0.3s ease;
            color: var(--accent-blue);
        }

        #add-button:hover {
            border-color: rgba(41, 151, 255, 0.4);
            background: rgba(41, 151, 255, 0.1);
        }

        #add-button svg {
            width: 18px;
            height: 18px;
        }

        #action-popup-menu {
            position: absolute;
            bottom: calc(100% - 12px);
            left: 16px;
            width: 260px;
            background: rgba(20, 20, 20, 0.9);
            backdrop-filter: blur(40px) saturate(200%);
            -webkit-backdrop-filter: blur(40px) saturate(200%);
            border: 1px solid var(--widget-border);
            border-radius: 16px;
            padding: 8px;
            box-shadow: none;
            z-index: 1000;
            opacity: 0;
            transform: translateY(10px);
            transition: opacity 0.3s ease, transform 0.3s ease;
            pointer-events: none;
        }

        #action-popup-menu.visible {
            opacity: 1;
            transform: translateY(0);
            pointer-events: auto;
        }

        .popup-menu-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 10px 12px;
            background: rgba(255, 255, 255, 0.02);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            border: 1px solid transparent;
            color: var(--text-primary);
            font-size: 0.9rem;
            font-weight: 500;
            border-radius: 10px;
            width: 100%;
            text-align: left;
            cursor: pointer;
            transition: all 0.2s ease;
            position: relative;
        }

        .popup-menu-item::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: transparent;
            border-radius: 10px;
            transition: background 0.2s ease;
        }

        .popup-menu-item:hover::before {
            background: rgba(41, 151, 255, 0.1);
        }

        .popup-menu-item:hover {
            border-color: rgba(41, 151, 255, 0.3);
        }

        .popup-menu-item svg {
            width: 18px;
            height: 18px;
            flex-shrink: 0;
        }

        #menu-research svg, #menu-upload svg {
            color: var(--accent-blue);
        }

        #message-input {
            flex-grow: 1;
            background-color: var(--input-bg);
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 22px;
            padding: 12px 20px;
            color: #fff;
            font-size: 16px;
            font-family: inherit;
            outline: none;
            transition: all 0.3s ease;
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
        }

        #message-input:focus {
            background-color: rgba(37, 37, 40, 0.8);
            border-color: rgba(41, 151, 255, 0.3);
        }

        #message-input.mode-research {
            color: var(--accent-blue);
            font-weight: 500;
        }

        #send-button {
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 50%;
            width: 36px;
            height: 36px;
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.3s ease;
            flex-shrink: 0;
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
            background: transparent;
        }

        #send-button svg {
            width: 18px;
            height: 18px;
            transition: transform 0.3s ease;
        }

        #send-button.mode-chat {
            background: var(--user-bubble-bg);
        }

        #send-button.mode-chat svg {
            transform: rotate(90deg);
            margin-left: 0;
            margin-top: -1px;
        }

        #send-button.mode-research {
            background: var(--accent-research-gradient);
        }

        #send-button.mode-research svg {
            transform: rotate(0deg);
        }

        #send-button:disabled {
            background: rgba(58, 58, 60, 0.6) !important;
            color: #636366;
            cursor: not-allowed;
        }

        #icon-send, #icon-research {
            display: none;
        }

        #send-button.mode-chat #icon-send {
            display: block;
        }

        #send-button.mode-research #icon-research {
            display: block;
        }

        #research-view {
            display: flex;
            flex-direction: column;
            width: 100vw;
            height: 100vh;
            position: fixed;
            top: 0;
            left: 0;
            z-index: 100;
            background: #000000;
            backdrop-filter: none;
            -webkit-backdrop-filter: none;
            box-shadow: none;
            border: none;
            transform: translateX(100%);
            transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1);
            overflow: hidden;
        }

        #research-view.visible {
            transform: translateX(0);
        }

        #research-header {
            padding: 16px 20px;
            padding-top: calc(16px + var(--safe-top));
            padding-left: 12px;
            justify-content: space-between;
            flex-shrink: 0;
            border-bottom: 1px solid var(--widget-border);
        }

        #research-back-button {
            background: transparent;
            border: none;
            color: var(--accent-blue);
            font-size: 0.95rem;
            font-weight: 500;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 4px;
            padding: 6px 10px;
            transition: color 0.2s ease;
            border-radius: 8px;
        }

        #research-back-button:hover {
            color: var(--text-primary);
            background: rgba(41, 151, 255, 0.1);
        }

        #research-back-button svg {
            width: 20px;
            height: 20px;
        }

        #research-title {
            font-size: 1.05rem;
            font-weight: 500;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 60%;
            letter-spacing: -0.02em;
        }

        #research-content {
            flex: 1;
            overflow-y: auto;
            overflow-x: hidden;
            padding: 1.75rem 1.25rem;
            padding-bottom: calc(1.75rem + var(--safe-bottom));
            display: flex;
            flex-direction: column;
            gap: 28px;
            -webkit-overflow-scrolling: touch;
        }

        #research-content::-webkit-scrollbar {
            width: 4px;
        }

        #research-content::-webkit-scrollbar-track {
            background: transparent;
        }

        #research-content::-webkit-scrollbar-thumb {
            background: rgba(255, 255, 255, 0.15);
            border-radius: 2px;
        }

        .research-section-title {
            font-size: 1.15rem;
            font-weight: 500;
            color: var(--accent-blue);
            padding-bottom: 10px;
            border-bottom: 1px solid var(--widget-border);
            margin-bottom: -10px;
            opacity: 0.95;
            letter-spacing: -0.01em;
        }

        .agent-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
        }

        .agent-card {
            background: rgba(28, 28, 30, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 22px;
            padding: 20px;
            display: flex;
            align-items: center;
            gap: 20px;
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
        }

        .agent-progress-donut {
            flex-shrink: 0;
        }

        .agent-progress-donut .donut-fg {
            transition: stroke-dashoffset 0.5s ease-out;
        }

        .agent-progress-donut .donut-text {
            font-size: 11px;
            font-weight: 600;
            fill: var(--text-primary);
        }

        .agent-card-info .agent-card-title {
            font-size: 0.95rem;
            font-weight: 500;
        }

        .agent-card-info .agent-card-status {
            font-size: 0.85rem;
            color: var(--text-secondary);
        }

        .similar-link-item, .webset-item {
            display: flex;
            align-items: center;
            gap: 16px;
            padding: 16px;
            background: rgba(28, 28, 30, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 14px;
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
        }

        .icon-placeholder {
            width: 40px;
            height: 40px;
            flex-shrink: 0;
            background: rgba(44, 44, 46, 0.6);
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .icon-placeholder svg {
            width: 20px;
            height: 20px;
            color: var(--text-secondary);
        }

        .item-text .item-title {
            font-size: 0.95rem;
            font-weight: 500;
            color: var(--text-primary);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .item-text .item-url {
            font-size: 0.8rem;
            color: var(--text-secondary);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        #research-options-modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            z-index: 99;
            display: flex;
            align-items: flex-end;
            justify-content: center;
            opacity: 0;
            transition: opacity 0.4s cubic-bezier(0.25, 1, 0.5, 1);
            pointer-events: none;
        }

        #research-options-modal-overlay.visible {
            opacity: 1;
            pointer-events: auto;
        }

        #research-options-modal {
            background: rgba(28, 28, 30, 0.95);
            border-radius: 24px 24px 0 0;
            border-top: 1px solid rgba(255, 255, 255, 0.08);
            width: 100%;
            max-width: 100%;
            padding: 24px;
            padding-top: 12px;
            padding-bottom: calc(24px + var(--safe-bottom));
            box-shadow: none;
            transform: translateY(100%);
            transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
        }

        #research-options-modal-overlay.visible #research-options-modal {
            transform: translateY(0);
        }

        .modal-handle {
            width: 40px;
            height: 4px;
            background: rgba(58, 58, 60, 0.5);
            border-radius: 2px;
            margin: 0 auto 20px;
        }

        #research-options-modal h2 {
            font-size: 1.15rem;
            font-weight: 500;
            text-align: center;
            margin-bottom: 12px;
            letter-spacing: -0.02em;
        }

        #research-goal-summary {
            font-size: 0.95rem;
            text-align: center;
            color: var(--text-secondary);
            margin-bottom: 24px;
            padding: 16px;
            background: rgba(44, 44, 46, 0.6);
            border-radius: 12px;
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
        }

        #toggle-advanced-options {
            background: none;
            border: none;
            color: var(--accent-blue);
            font-size: 0.95rem;
            font-weight: 500;
            cursor: pointer;
            margin-bottom: 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            padding: 8px;
            border-radius: 8px;
            transition: background 0.2s ease;
        }

        #toggle-advanced-options:hover {
            background: rgba(41, 151, 255, 0.1);
        }

        #advanced-options-container {
            border-top: 1px solid var(--widget-border);
            padding-top: 24px;
            margin-bottom: 24px;
            display: none;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-group label {
            display: block;
            font-size: 0.85rem;
            color: var(--text-secondary);
            margin-bottom: 8px;
            font-weight: 500;
            letter-spacing: -0.01em;
        }

        .form-group input, .form-group select {
            width: 100%;
            background-color: rgba(44, 44, 46, 0.8);
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 12px;
            padding: 12px 14px;
            color: #fff;
            font-size: 0.98rem;
            font-family: inherit;
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
            transition: all 0.2s ease;
        }

        .form-group input:focus, .form-group select:focus {
            border-color: rgba(41, 151, 255, 0.3);
            background-color: rgba(44, 44, 46, 1);
        }

        .form-group input[type="date"] {
            color-scheme: dark;
            -webkit-appearance: none;
        }

        #submit-research-task {
            width: 100%;
            background: rgba(41, 151, 255, 0.15);
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
            color: var(--accent-blue);
            border: 1px solid rgba(41, 151, 255, 0.3);
            border-radius: 12px;
            padding: 12px;
            font-size: 0.95rem;
            font-weight: 500;
            cursor: pointer;
            margin-bottom: 12px;
            transition: all 0.2s ease;
        }

        #submit-research-task:hover {
            background: rgba(41, 151, 255, 0.25);
            border-color: rgba(41, 151, 255, 0.5);
        }

        #cancel-research-task {
            width: 100%;
            background: rgba(255, 255, 255, 0.02);
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
            color: var(--text-secondary);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 12px;
            padding: 12px;
            font-size: 0.9rem;
            font-weight: 500;
            cursor: pointer;
            text-align: center;
            transition: all 0.2s ease;
        }

        #cancel-research-task:hover {
            background: rgba(255, 255, 255, 0.06);
            border-color: rgba(255, 255, 255, 0.15);
            color: var(--text-primary);
        }
    </style>
</head>

<body>
    <canvas id="canvas-bg"></canvas>

    <div id="sidebar-overlay"></div>
