                    <svg id="icon-research" xmlns="" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M11.29 2.234a.75.75 0 0 0-1.071 1.071 7.5 7.5 0 0 1 2.39 7.195.75.75 0 1 0 1.488-.287 9 9 0 0 0-2.86-8.622.75.75 0 0 0-.947-.357Z" clip-rule="evenodd"/><path fill-rule="evenodd" d="M8.71 2.234a.75.75 0 0 1 .947-.357 9 9 0 0 1 2.86 8.622.75.75 0 1 1-1.488-.287 7.5 7.5 0 0 0-2.39-7.195.75.75 0 0 1-.929-1.071l.001-.001.001-.001Z" clip-rule="evenodd"/><path fill-rule="evenodd" d="M10 18.25a8.25 8.25 0 1 0 0-16.5 8.25 8.25 0 0 0 0 16.5ZM10 3.25a6.75 6.75 0 1 0 0 13.5 6.75 6.75 0 0 0 0-13.5Z" clip-rule="evenodd"/></svg>
