    <script type="module">
        const $ = (q, r = document) => r.querySelector(q);
        const $$ = (q, r = document) => Array.from(r.querySelectorAll(q));
        const state = {
            chats: [],
            activeChatId: null,
            engine: null,
            engineReady: false,
            initializing: false,
            model: 'Qwen2.5-1.5B-Instruct-q4f32_1-MLC',
            researchArmed: false,
            researchTask: null
        };
        const chatHistoryEl = $('#chat-history');
        const messageForm = $('#message-form');
        const messageInput = $('#message-input');
        const sendButton = $('#send-button');
        const addButton = $('#add-button');
        const popupMenu = $('#action-popup-menu');
        const fileInput = $('#file-input');
        const sidebar = $('#sidebar');
        const sidebarOverlay = $('#sidebar-overlay');
        const pastChatsContainer = $('#past-chats-container');
        const menuToggle = $('#menu-toggle');
        const sidebarClose = $('#sidebar-close');
        const newChatButton = $('#new-chat-button');
        const researchView = $('#research-view');
        const researchContent = $('#research-content');
        const researchBack = $('#research-back-button');
        const researchTitle = $('#research-title');
        const researchModalOverlay = $('#research-options-modal-overlay');
        const researchGoalSummary = $('#research-goal-summary');
        const toggleAdvancedBtn = $('#toggle-advanced-options');
        const advancedContainer = $('#advanced-options-container');
        const submitResearchBtn = $('#submit-research-task');
        const cancelResearchBtn = $('#cancel-research-task');
        const searchTypeEl = $('#search-type');
        const categoryEl = $('#category');
        const userLocationEl = $('#user-location');
        const languageEl = $('#language');
        const modelSelectEl = $('#model-select');
        const maxResultsEl = $('#max-results');
        const startDateEl = $('#start-date');
        const endDateEl = $('#end-date');
        const startCrawlEl = $('#start-crawl-date');
        const endCrawlEl = $('#end-crawl-date');
        const sourceUrlsEl = $('#source-urls');
        const canvas = $('#canvas-bg');
        let renderer, scene, camera, particles, clock;
        function initBg() {
            renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
            renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
            renderer.setSize(window.innerWidth, window.innerHeight);
            scene = new THREE.Scene();
            camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 1, 2000);
            camera.position.z = 500;
            const geometry = new THREE.BufferGeometry();
            const count = 1800;
            const positions = new Float32Array(count * 3);
            const colors = new Float32Array(count * 3);
            for (let i = 0; i < count; i++) {
                const r = 400;
                positions[i * 3 + 0] = (Math.random() - 0.5) * r * 2;
                positions[i * 3 + 1] = (Math.random() - 0.5) * r * 2;
                positions[i * 3 + 2] = (Math.random() - 0.5) * r * 2;
                colors[i * 3 + 0] = 0.2 + Math.random() * 0.3;
                colors[i * 3 + 1] = 0.5 + Math.random() * 0.3;
                colors[i * 3 + 2] = 1.0;
            }
            geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
            geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
            const material = new THREE.PointsMaterial({ size: 2, vertexColors: true, opacity: 0.9, transparent: true });
            particles = new THREE.Points(geometry, material);
            scene.add(particles);
            const ambient = new THREE.AmbientLight(0x335577, 0.6);
            scene.add(ambient);
            clock = new THREE.Clock();
            animate();
            window.addEventListener('resize', onResize);
        }
        function onResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }
        function animate() {
            requestAnimationFrame(animate);
            const t = clock.getElapsedTime();
            particles.rotation.y = t * 0.02;
            particles.rotation.x = Math.sin(t * 0.1) * 0.02;
            renderer.render(scene, camera);
        }
        function uuid() { return 'xxxxxxxx'.replace(/x/g, () => (Math.random() * 16 | 0).toString(16)) + Date.now().toString(36); }
        function saveState() { localStorage.setItem('tiffy_chats', JSON.stringify({ chats: state.chats, activeChatId: state.activeChatId })); }
        function loadState() {
            const raw = localStorage.getItem('tiffy_chats');
            if (!raw) return;
            try {
                const parsed = JSON.parse(raw);
                if (parsed && Array.isArray(parsed.chats)) {
                    state.chats = parsed.chats;
                    state.activeChatId = parsed.activeChatId || (state.chats[0] ? state.chats[0].id : null);
                }
            } catch(e) {}
        }
        function createChat(title = 'Új beszélgetés') {
            const chat = { id: uuid(), title, createdAt: Date.now(), messages: [] };
            state.chats.unshift(chat);
            state.activeChatId = chat.id;
            saveState();
            renderSidebar();
            renderActiveChat();
        }
        function updateChatTitleFromFirstUserMessage(chat) {
            const first = chat.messages.find(m => m.role === 'user');
            if (first) {
                chat.title = first.content.trim().slice(0, 40) || chat.title;
            }
        }
        function getActiveChat() { return state.chats.find(c => c.id === state.activeChatId) || null; }
        function renderSidebar() {
            pastChatsContainer.innerHTML = '';
            state.chats.forEach(chat => {
                const item = document.createElement('div');
                item.className = 'past-chat-item' + (chat.id === state.activeChatId ? ' active' : '');
